// insights-page.js: /insights/ bootstrap (spec 108).
//
// The page ships every post as a static row (generated by
// scripts/gen-post-pages.mjs), so it reads fine without JS. This module swaps
// those rows for the live list: search, tag filters and engagement chips.

// Sibling modules load with this module's own ?v= query, so a cache-bust on
// the page's script tag reaches them too.
const V = new URL(import.meta.url).search;

async function boot() {
    const root = document.querySelector("[data-posts-root]");
    if (!root) return;
    let metricsApi = null;
    try {
        const r = await fetch("content/profile.json", { cache: "no-cache" });
        if (r.ok) metricsApi = (await r.json())?.links?.metricsApi || null;
    } catch {
        // No metrics chips, everything else still works.
    }
    const { initPostsList } = await import(`./posts-list.js${V}`);
    await initPostsList(root, { metricsApi });
}

boot().catch((err) => console.warn("[insights] failed to init", err));
